export function adminMessagesFor(locale: string) {
  if (locale === "va") return adminMessageBundles.ca;
  if (locale === "es" || locale === "eu" || locale === "gl" || locale === "ca") return adminMessageBundles[locale];
  return adminMessageBundles.en;
}
